; bcd.asm -- chapter 10: a BCD score times ten and divided by ten
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "bcd.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
score   EQU RAM_START          ; six BCD digits, the first two first
out     EQU RAM_START + 3      ; for each score: digit and score, both ways
        ld hl, score
        ld (hl), $01
        inc hl
        ld (hl), $23
        inc hl
        ld (hl), $45            ; the score: 012345
up0:    call bcd10
        ld (out+0), a           ; the digit that fell off
        ld hl, (score)
        ld (out+1), hl
        ld a, (score + 2)
        ld (out+3), a
        ld hl, score
        ld (hl), $01
        inc hl
        ld (hl), $23
        inc hl
        ld (hl), $45            ; the score: 012345
down0:  call bcd01
        ld (out+4), a           ; the digit that fell off
        ld hl, (score)
        ld (out+5), hl
        ld a, (score + 2)
        ld (out+7), a
        ld hl, score
        ld (hl), $99
        inc hl
        ld (hl), $99
        inc hl
        ld (hl), $99            ; the score: 999999
up1:    call bcd10
        ld (out+8), a           ; the digit that fell off
        ld hl, (score)
        ld (out+9), hl
        ld a, (score + 2)
        ld (out+11), a
        ld hl, score
        ld (hl), $99
        inc hl
        ld (hl), $99
        inc hl
        ld (hl), $99            ; the score: 999999
down1:  call bcd01
        ld (out+12), a          ; the digit that fell off
        ld hl, (score)
        ld (out+13), hl
        ld a, (score + 2)
        ld (out+15), a
        ld hl, score
        ld (hl), $00
        inc hl
        ld (hl), $07
        inc hl
        ld (hl), $40            ; the score: 000740
up2:    call bcd10
        ld (out+16), a          ; the digit that fell off
        ld hl, (score)
        ld (out+17), hl
        ld a, (score + 2)
        ld (out+19), a
        ld hl, score
        ld (hl), $00
        inc hl
        ld (hl), $07
        inc hl
        ld (hl), $40            ; the score: 000740
down2:  call bcd01
        ld (out+20), a          ; the digit that fell off
        ld hl, (score)
        ld (out+21), hl
        ld a, (score + 2)
        ld (out+23), a
        ld hl, score
        ld (hl), $10
        inc hl
        ld (hl), $00
        inc hl
        ld (hl), $00            ; the score: 100000
up3:    call bcd10
        ld (out+24), a          ; the digit that fell off
        ld hl, (score)
        ld (out+25), hl
        ld a, (score + 2)
        ld (out+27), a
        ld hl, score
        ld (hl), $10
        inc hl
        ld (hl), $00
        inc hl
        ld (hl), $00            ; the score: 100000
down3:  call bcd01
        ld (out+28), a          ; the digit that fell off
        ld hl, (score)
        ld (out+29), hl
        ld a, (score + 2)
        ld (out+31), a
stop:   jr stop

; bcd10: the six digits at score, first digits first, one digit to the
;        left: the score times ten, with 0 coming in at the right. A = the
;        digit that falls off the left.
bcd10:  ld hl, score + 2        ; the last two digits
        xor a                   ; the digit that comes in: 0
        rld                     ; A's digit in at the bottom of (HL), the
        dec hl                  ; top digit of (HL) out into A
        rld
        dec hl
        rld
        ret

; bcd01: the six digits one digit to the right: the score divided by ten.
;        A = the digit that falls off the right, the remainder.
bcd01:  ld hl, score            ; the first two digits
        xor a                   ; 0 comes in at the left
        rrd                     ; A's digit in at the top of (HL), the
        inc hl                  ; bottom digit of (HL) out into A
        rrd
        inc hl
        rrd
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
